        throw new Error("Invalid expression");
    }

    // Handle division by zero
    if (expr.includes('/0')) {
        throw new Error("Division by zero");
    }

    // Parse and evaluate the expression with proper precedence
    try {
        // First, handle parentheses recursively
        while (expr.includes('(')) {
            const parenMatch = expr.match(/\([^()]+\)/);
            if (!parenMatch) {
                throw new Error("Mismatched parentheses");
            }
            const innerExpr = parenMatch[0].slice(1, -1);
            const result = evaluate(innerExpr);
            expr = expr.replace(parenMatch[0], result);
        }

        // Handle multiplication and division (left to right)
        let i = 0;
        while (i < expr.length) {
            if (expr[i] === '*') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                const result = left * right;
                const leftStart = getNumberStart(expr, i - 1, true);
                const rightEnd = getNumberEnd(expr, i + 1, false);
                expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd + 1);
                i = leftStart + result.toString().length;
            } else if (expr[i] === '/') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                if (right === 0) {
                    throw new Error("Division by zero");
                }
                const result = left / right;
                const leftStart = getNumberStart(expr, i - 1, true);
                const rightEnd = getNumberEnd(expr, i + 1, false);
                expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd + 1);
                i = leftStart + result.toString().length;
            } else {
                i++;
            }
        }

        // Handle addition and subtraction (left to right)
        i = 0;
        while (i < expr.length) {
            if (expr[i] === '+') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                const result = left + right;
                const leftStart = getNumberStart(expr, i - 1, true);
                const rightEnd = getNumberEnd(expr, i + 1, false);
                expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd + 1);
                i = leftStart + result.toString().length;
            } else if (expr[i] === '-') {
                // Check if this is a minus sign (unary) or subtraction operator
                if (i === 0 || expr[i-1] === '+' || expr[i-1] === '-' || expr[i-1] === '*' || expr[i-1] === '/') {
                    // This is a unary minus, continue
                    i++;
                } else {
                    const left = parseFloat(getNumber(expr, i - 1, true));
                    const right = parseFloat(getNumber(expr, i + 1, false));
                    const result = left - right;
                    const leftStart = getNumberStart(expr, i - 1, true);
                    const rightEnd = getNumberEnd(expr, i + 1, false);
                    expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd + 1);
                    i = leftStart + result.toString().length;
                }
            } else {
                i++;
            }
        }

        // Final check - should be a single number now
        const finalResult = parseFloat(expr);
        if (isNaN(finalResult)) {
            throw new Error("Invalid expression");
        }

        return finalResult;
    } catch (e) {
        throw new Error("Invalid expression");
    }
}

/**
 * Helper function to extract a number from an expression
 * @param {string} expr - The expression
 * @param {number} pos - Position to start looking
 * @param {boolean} left - Whether to look left or right
 * @returns {string} - The number as a string
 */
function getNumber(expr, pos, left) {
    if (left) {
        // Look for a number to the left
        let start = pos;
        while (start >= 0 && (/[0-9.]/.test(expr[start]))) {
            start--;
        }
        start++;
        return expr.substring(start, pos + 1);
    } else {
        // Look for a number to the right
        let end = pos;
        while (end < expr.length && (/[0-9.]/.test(expr[end]))) {
            end++;
        }
        return expr.substring(pos, end);
    }
}

/**
 * Helper function to find the start position of a number
 * @param {string} expr - The expression
 * @param {number} pos - Position to start looking
 * @param {boolean} left - Whether to look left or right
 * @returns {number} - The start position
 */
function getNumberStart(expr, pos, left) {
    if (left) {
        let start = pos;
        while (start >= 0 && (/[0-9.]/.test(expr[start]))) {
            start--;
        }
        return start + 1;
    } else {
        return pos;
    }
}

/**
 * Helper function to find the end position of a number
 * @param {string} expr - The expression
 * @param {number} pos - Position to start looking
 * @param {boolean} right - Whether to look right or left
 * @returns {number} - The end position
 */
function getNumberEnd(expr, pos, right) {
    if (right) {
        let end = pos;
        while (end < expr.length && (/[0-9.]/.test(expr[end]))) {
            end++;
        }
        return end - 1;
    } else {
        return pos;
    }
}

