/**
 * Evaluates a mathematical expression containing +, -, *, / operators
 * @param {string} expr - The expression to evaluate
 * @returns {number} - The result of the evaluation
 */
function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error("Empty expression");
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error("Invalid characters in expression");
    }

    // Check for invalid patterns
    if (expr.match(/[\+\-\*\/]{2,}/) || expr.match(/[+\-*/]$/)) {
        throw new Error("Invalid expression");
    }

    // Handle division by zero
    if (expr.includes('/0')) {
        throw new Error("Division by zero");
    }

    // Parse and evaluate the expression with proper precedence
    try {
        // First, handle parentheses recursively
        while (expr.includes('(')) {
            const parenMatch = expr.match(/\([^()]+\)/);
            if (!parenMatch) {
                throw new Error("Mismatched parentheses");
            }
            const innerExpr = parenMatch[0].slice(1, -1);
            const result = evaluate(innerExpr);
            expr = expr.replace(parenMatch[0], result);
        }

        // Handle multiplication and division (left to right)
        let i = 0;
        while (i < expr.length) {
            if (expr[i] === '*') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                const result = left * right;
                expr = replaceAt(expr, i - getNumberLength(expr, i - 1, true), 
                                i + getNumberLength(expr, i + 1, false), result.toString());
                i = 0; // Reset to start over
            } else if (expr[i] === '/') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                if (right === 0) {
                    throw new Error("Division by zero");
                }
                const result = left / right;
                expr = replaceAt(expr, i - getNumberLength(expr, i - 1, true), 
                                i + getNumberLength(expr, i + 1, false), result.toString());
                i = 0; // Reset to start over
            } else {
                i++;
            }
        }

        // Handle addition and subtraction (left to right)
        i = 0;
        while (i < expr.length) {
            if (expr[i] === '+') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                const result = left + right;
                expr = replaceAt(expr, i - getNumberLength(expr, i - 1, true), 
                                i + getNumberLength(expr, i + 1, false), result.toString());
                i = 0; // Reset to start over
            } else if (expr[i] === '-') {
                // Special case: negative numbers
                if (i === 0 || expr[i-1] === '(' || expr[i-1] === '+' || expr[i-1] === '-' || expr[i-1] === '*' || expr[i-1] === '/') {
                    // This is a negative number, not a subtraction
                    i++;
                } else {
                    const left = parseFloat(getNumber(expr, i - 1, true));
                    const right = parseFloat(getNumber(expr, i + 1, false));
                    const result = left - right;
                    expr = replaceAt(expr, i - getNumberLength(expr, i - 1, true), 
                                    i + getNumberLength(expr, i + 1, false), result.toString());
                    i = 0; // Reset to start over
                }
            } else {
                i++;
            }
        }

        // At this point, expr should be a single number
        return parseFloat(expr);
    } catch (e) {
        throw new Error("Invalid expression");
    }
}

// Helper function to extract a number from the expression
function getNumber(expr, pos, isLeft) {
    if (pos < 0 || pos >= expr.length) return "";

    let start = pos;
    let end = pos;

    // For left side, move backwards to find the start of the number
    if (isLeft) {
        while (start >= 0 && (/[0-9.]/.test(expr[start]))) {
            start--;
        }
        start++; // Move back to the first digit
    } else {
        // For right side, move forward to find the end of the number
        while (end < expr.length && (/[0-9.]/.test(expr[end]))) {
            end++;
        }
    }

    return expr.substring(start, end);
}

// Helper function to get the length of a number
function getNumberLength(expr, pos, isLeft) {
    if (pos < 0 || pos >= expr.length) return 0;

    let start = pos;
    let end = pos;

    // For left side, move backwards to find the start of the number
    if (isLeft) {
        while (start >= 0 && (/[0-9.]/.test(expr[start]))) {
            start--;
        }
        start++; // Move back to the first digit
    } else {
        // For right side, move forward to find the end of the number
        while (end < expr.length && (/[0-9.]/.test(expr[end]))) {
            end++;
        }
    }

    return end - start;
}

// Helper function to replace a substring in a string
function replaceAt(str, start, end, replacement) {
    return str.substring(0, start) + replacement + str.substring(end);
}

