 * @param {string} expr - The expression to evaluate
 * @returns {number} - The result of the evaluation
 */
function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error("Empty expression");
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error("Invalid characters in expression");
    }

    // Check for invalid patterns
    if (expr.match(/[\+\-\*\/]{2,}/) || expr.match(/[+\-*/]$/)) {
        throw new Error("Invalid expression");
    }

    // Handle division by zero
    if (expr.includes('/0')) {
        throw new Error("Division by zero");
    }

    // Simple approach: use a stack-based evaluation with proper precedence
    try {
        // First, handle parentheses recursively
        while (expr.includes('(')) {
            const parenMatch = expr.match(/\([^()]+\)/);
            if (!parenMatch) {
                throw new Error("Mismatched parentheses");
            }
            const innerExpr = parenMatch[0].slice(1, -1);
            const result = evaluate(innerExpr);
            expr = expr.replace(parenMatch[0], result);
        }

        // Parse and evaluate with proper precedence
        // First pass: handle multiplication and division
        let i = 0;
        while (i < expr.length) {
            if (expr[i] === '*') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                const result = left * right;
                const leftStart = getNumberStart(expr, i - 1, true);
                const rightEnd = getNumberEnd(expr, i + 1, false);
                expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd + 1);
                i = leftStart + result.toString().length;
            } else if (expr[i] === '/') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                if (right === 0) {
                    throw new Error("Division by zero");
                }
                const result = left / right;
                const leftStart = getNumberStart(expr, i - 1, true);
                const rightEnd = getNumberEnd(expr, i + 1, false);
                expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd + 1);
                i = leftStart + result.toString().length;
            } else {
                i++;
            }
        }

        // Second pass: handle addition and subtraction
        i = 0;
        while (i < expr.length) {
            if (expr[i] === '+') {
                const left = parseFloat(getNumber(expr, i - 1, true));
                const right = parseFloat(getNumber(expr, i + 1, false));
                const result = left + right;
                const leftStart = getNumberStart(expr, i - 1, true);
                const rightEnd = getNumberEnd(expr, i + 1, false);
                expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd + 1);
                i = leftStart + result.toString().length;
            } else if (expr[i] === '-') {
                // Check if this is a minus sign (unary) or subtraction operator
                if (i === 0 || expr[i-1] === '(' || expr[i-1] === '+' || expr[i-1] === '-' || expr[i-1] === '*' || expr[i-1] === '/') {
                    // This is a unary minus, continue
                    i++;
                } else {
                    const left = parseFloat(getNumber(expr, i - 1, true));
                    const right = parseFloat(getNumber(expr, i + 1, false));
                    const result = left - right;
                    const leftStart = getNumberStart(expr, i - 1, true);
                    const rightEnd = getNumberEnd(expr, i + 1, false);
                    expr = expr.substring(0, leftStart) + result + expr.substring(rightEnd + 1);
                    i = leftStart + result.toString().length;
                }
            } else {
                i++;
            }
        }

        // Final check - should be a single number now
        const finalResult = parseFloat(expr);
        if (isNaN(finalResult)) {
            throw new Error("Invalid expression");
        }

        return finalResult;
    } catch (e) {
        throw new Error("Invalid expression");
    }
}

