def neighbors(self, a):
    """Return a sorted list of (b, weight) tuples for neighbors of node a."""
    if a not in self.edges:
        return []

    # Return neighbors sorted by node name
    return sorted([(b, weight) for b, weight in self.edges[a].items()])

def bfs(self, start):
    """Return nodes reachable from start in breadth-first order, visiting neighbors in sorted order.
    Raises KeyError if start is not in the graph."""
    if start not in self.nodes_set:
        raise KeyError(f"Start node {start} not in graph")

    visited = set()
    queue = [start]
    result = []

    while queue:
        node = queue.pop(0)
        if node not in visited:
            visited.add(node)
            result.append(node)
            # Add neighbors in sorted order
            for neighbor, _ in self.neighbors(node):
                if neighbor not in visited:
                    queue.append(neighbor)

    return result

class Cache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }

    this.capacity = capacity;
    this.map = new Map();
  }

  set(key, value) {
    // If key already exists, update it and move to end (most recently used)
    if (this.map.has(key)) {
      this.map.delete(key);
    }

    // If cache is full, remove the least recently used item (first item)
    if (this.map.size >= this.capacity) {
      const firstKey = this.map.keys().next().value;
      this.map.delete(firstKey);
    }

    // Add the new key-value pair at the end (most recently used)
    this.map.set(key, value);
  }

  get(key) {
    // If key doesn't exist, return undefined
    if (!this.map.has(key)) {
      return undefined;
    }

    // Get the value and move the key to the end (mark as most recently used)
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value);

    return value;
  }

  has(key) {
    return this.map.has(key);
  }

  size() {
    return this.map.size;
  }

  delete(key) {
    return this.map.delete(key);
  }

  clear() {
    this.map.clear();
  }
}

def score(self, student, assignment):
    if student not in self.students or assignment not in self.students[student]:
        return None
    return self.students[student][assignment]

def percent(self, student):
    if student not in self.students:
        raise KeyError("Unknown student")

    total_points = 0
    total_max_points = 0

    for assignment, points in self.students[student].items():
        total_points += points
        total_max_points += self.assignments[assignment]

    if total_max_points == 0:
        return None

    return round((total_points / total_max_points) * 100, 2)
